from pathlib import Path
import hashlib,json,shutil
frozen=json.loads(Path('rag/eval/baselines/langgraph_candidate_v1/manifest.json').read_text())
for filename in ('rag/service/ticket_service.py','rag/service/intent_classifier.py','rag/service/store_contract.py','rag/service/semantic_router.py','rag/service/routing_prototypes.json','rag/retrieval/search_chunks.py','rag/service/retrieval_server.py'):
    assert hashlib.sha256(Path(filename).read_bytes()).hexdigest()==frozen['files'][filename],filename
backup=Path('deploy/backups/answer-evidence-2026-10-12');backup.mkdir(parents=True,exist_ok=False)
for filename in ('answer_service.py','ask_graph.py','mixed_service.py'):
    shutil.copyfile(Path('rag/service')/filename,backup/filename)
(backup/'manifest.json').write_text(json.dumps({'unit_tests_passed':64,'new_prompt':True,'no_router_or_search_change':True,'no_secrets_archived':True}))
for filename in ('answer_service.py','answer_evidence_guards.py','ask_graph.py','mixed_service.py'):
    shutil.copyfile(Path('/tmp/travel-answer-evidence-stage/service')/filename,Path('rag/service')/filename)
for filename in ('test_answer_evidence_guards.py','test_ask_graph.py','test_mixed_service.py'):
    shutil.copyfile(Path('/tmp/travel-answer-evidence-stage/eval')/filename,Path('rag/eval')/filename)
print('Evidence fixes deployed; SQL, router, thresholds, /ask entry and search unchanged')
PY
